INSERT INTO `wfl_external_fiscal_observations` (`id_efo`, `project_id_efo`, `fiscal_id_efo`, `observation_efo`, `fixed_by_efo`, `fix_detail_efo`, `fixed_date_efo`, `status_id_efo`, `entry_date_efo`, `fixed_efo`, `deleted_efo`, `createdon_efo`, `createdby_efo`, `editedon_efo`, `editedby_efo`) VALUES (1,1113,62,'01/08/2020',NULL,'',NULL,46,'2020-08-31 09:10:08',0,0,'2020-08-31 09:10:08',2,'0000-00-00 00:00:00',NULL),(2,1030,62,'Estimado Mario:\r\n \r\nFavor corregir las siguientes observaciones de Contruccion del proyecto de referencia (RO.19.0201):\r\n \r\n1)    Punto 4: Corregir Empalme de 1 Fase de MT.(Instalar Cable del Proyecto) No se acepta MRT\r\n2)    Punto 8: Corregir Informe de Equipo instalado en la Red. AS BUILT\r\n',NULL,'',NULL,33,'2020-09-14 11:18:06',0,0,'2020-09-14 11:18:06',2,'0000-00-00 00:00:00',NULL),(3,584,62,'Estimado Mario:\r\nFavor corregir la observación resaltada en líneas de abajo:\r\n4, Retesar y Arreglar línea de BT entre Punto 2 y 3. Se avisó vía teléfono con fotografías a Rubén Aguirre.\r\n \r\nAguardo Fecha de corrección. \r\n',NULL,'',NULL,38,'2020-08-19 11:22:43',0,0,'2020-09-14 11:22:43',2,'0000-00-00 00:00:00',NULL),(4,903,62,'Estimado Mario:\r\n \r\nFavor informar lo siguiente:\r\n•         El motivo por que no se instaló las Mallas Cima Simple en el Punto 1 (VC1-1).\r\n•         Porque se cortó el cable de BT. en el Punto 2 (Retazado) Esto ocasiona más puntos calientes en la Línea BT. \r\n \r\nSI hubiera algún respaldo, siempre hacerlo conocer por vía correo, Caso contrario:\r\nPUNTO 1 (FALTA  INSTALAR (3) MALLAS CIMA SIMPLE)\r\n',NULL,'',NULL,35,'2020-08-17 07:54:09',0,0,'2020-09-17 07:54:09',2,'0000-00-00 00:00:00',NULL),(5,1040,62,'Estimado Mario:\r\n \r\nInformarte al Respecto:\r\n•         RO.19.0357 (El Proyecto está construido con Material VIEJO) Por ejemplo el J9M. se avisó ayer 10/08/2020 a Rubén Aguirre. \r\n \r\nAsí que favor tomar en cuenta para su listado de abajo. \r\n \r\n',NULL,'',NULL,34,'2020-07-11 07:55:37',0,0,'2020-09-17 07:55:37',2,'0000-00-00 00:00:00',NULL),(6,959,62,'Estimado Mario:\r\n \r\nFavor Informar por qué Motivo se RETAZEO el conductor del Proyecto RA.20.0258 (Total Proyecto 75 Metros), quedo en 2 pedazos de 40+35 Metros.\r\nEl diseño se aprobó en el punto 2 con Estructura de Paso J20 (Porqué se hizo J22D + Conectores…?).\r\n \r\nEstaré atento a tu comentarios, para proceder al cierre del proyecto.\r\n \r\nSaludos \r\nRolando DC\r\n',NULL,'',NULL,38,'2020-06-08 07:56:55',0,0,'2020-09-17 07:56:55',2,'0000-00-00 00:00:00',NULL);
